CREATE TABLE IF NOT EXISTS "fdp_t" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "fdp_t_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"title" varchar(255) NOT NULL,
	"staff_id" integer,
	"faculty_name" varchar(150),
	"organizer" varchar(255),
	"collaborator" varchar(255),
	"mode" varchar(20) DEFAULT 'ONLINE',
	"venue" varchar(255),
	"start_date" date,
	"end_date" date,
	"academic_year" varchar(20),
	"subject_id" integer,
	"department_id" integer,
	"topics" text,
	"remarks" text,
	"created_by" integer,
	"updated_by" integer,
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now(),
	"display" varchar(1) DEFAULT 'Y'
);
